package in.simplifymoney.ledgersync.store;
import in.simplifymoney.ledgersync.model.*; import java.util.*;
public final class ConsistencyChecker { private final SqlLedgerStore sql; private final DocumentStore documents; public ConsistencyChecker(SqlLedgerStore s,DocumentStore d){sql=s;documents=d;} public List<Divergence> check(){Map<String,NormalizedTxn>a=new HashMap<>();for(NormalizedTxn t:sql.all())a.put(key(t),t);Map<String,NormalizedTxn>b=new HashMap<>();for(NormalizedTxn t:sql.all()){for(String id:t.sourceMessageIds()){var x=documents.byMessageId(id);if(x.isPresent()){b.put(key(x.get()),x.get());break;}}}List<Divergence>out=new ArrayList<>();for(var e:a.entrySet())if(!b.containsKey(e.getKey()))out.add(new Divergence("missing transaction "+e.getKey(),e.getValue().toString(),"missing"));for(var e:b.entrySet())if(!a.containsKey(e.getKey()))out.add(new Divergence("unexpected transaction "+e.getKey(),"missing",e.getValue().toString()));return out;}private static String key(NormalizedTxn t){return t.accountLast4()+"|"+t.occurredAt()+"|"+t.direction()+"|"+t.amount()+"|"+t.category()+"|"+t.merchant();} public record Divergence(String what,String inSql,String inDocuments){} }
